from research_helpers import *
a=ev('https://mvpadjuvants.com/wp-content/uploads/2017/09/MVP140620GLB_MVPbrochure-1.pdf','Eight adjuvant formulations in brochure currently linked from product overview; vaccine ingredients, not standalone finished vaccines.')
b=ev('https://mvpadjuvants.com/products-overview/','Current commercial overview links reviewed brochure and confirms Phibro business affiliation.')
c=ev('https://www.pahc.com/product_services/phibro-biotechnics/','Named commercial microbial remediation, cleaning and plant products; contract-manufacturing service steps not separate product SKUs.')
d=ev('https://www.pahc.com/product_services/ethanol/products-services/yeast-solutions/','Kinetx engineered yeast, PhibroADY selected yeast and FortiPhi fermentation-nutrition offerings; quality programme CertiPhied not a separate product.')
e=ev('https://www.pahc.com/product_services/ethanol/products-services/enzymes/','Two named industrial fermentation enzymes and functions verified.')
products=[]
for n,desc in [('EMULSIGEN','Oil-in-water vaccine adjuvant.'),('EMULSIGEN-D','Dual-action oil-in-water vaccine adjuvant formulation.'),('EMULSIGEN-DL90','Dual-action oil-in-water vaccine adjuvant formulation.'),('EMULSIGEN-P','Dual-action oil-in-water vaccine adjuvant formulation.'),('EMULSIGEN-BCL','Dual-action oil-in-water vaccine adjuvant formulation.'),('EMULSIMUNE','Stabilized emulsion adjuvant designed for fish vaccines.'),('CARBIGEN','Polymer vaccine adjuvant with mucosal-delivery applications.'),('POLYGEN','Polymer vaccine adjuvant for immune-response stimulation.')]:
 products.append(p(n,desc,a,life='commercial',roles=['commercial_partner'],typ='product',sub='research_tools',evidence=[a,b]))
for n,desc in [('Munox','Microbial formulations for degradation of fats, oils, grease, hydrocarbons and other organics.'),('Bacilox XL DL RTU','Spore-forming microbial cleaning and environmental-control formulation.'),('Bacilox XL HS RTU','Spore-forming microbial cleaning and environmental-control formulation.'),('Bacilox XL OE Scented','Scented microbial cleaning and odor-control formulation.'),('Bacilox XL OE Unscented','Unscented microbial cleaning and odor-control formulation.'),('Phibro Abundance','Bacillus-based biological fertilizer companion product family.'),('MicroAlly','Bacillus-based biological seed treatment family; wettable-powder and concentrated-liquid formats.')]:
 products.append(p(n,desc,c,life='commercial',roles=['manufacturer'],typ='product',sub='industrial_biotechnology'))
for n,desc in [('Kinetx','Engineered glucoamylase-expressing yeast family for industrial ethanol fermentation.'),('PhibroADY','Selected Saccharomyces cerevisiae yeast for fuel ethanol and beverage alcohol fermentation.'),('FortiPhi','Yeast nutrition formulation family including inactivated yeast cultures for industrial fermentation.')]:
 products.append(p(n,desc,d,life='commercial',typ='product',sub='industrial_biotechnology'))
for n,desc in [('NitriPhi','Protease enzyme supporting nitrogen availability during ethanol fermentation.'),('XylaPlus','Thermostable xylanase for processing corn fibre during ethanol production.')]:
 products.append(p(n,desc,e,life='commercial',typ='product',sub='industrial_biotechnology'))
co=dict(company_id='cmp_32d19ad0-588e-4a28-97a4-136c571d95f0',products=products,evidence=[a,b,c,d,e],status='partial',coverage_note='Adds 20 commercial adjuvant, microbial and fermentation offerings to prior 24 veterinary/microbial records (44 total). Families and formulations are not all unique molecules or orderable pack sizes. Partial: full regional vaccine and medicated-feed catalogues, additional microbial/yeast grades, aquaculture products and legacy offerings remain. Exact adjuvant territories not inferred from broad worldwide-use statements; ordinary cleaners and mineral nutrients excluded unless specifically part of named bioprocess formulation.')
assert len(products)==20
(out/'batch-0403.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
